def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 500:
                rich_opponents += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if very_urgent:
        bid = max(92.0, highest_prev + 3.0)
    elif my_urgent:
        bid = max(72.0, avg_prev + 2.0)
    else:
        if slots >= 2:
            bid = 26.0
            if highest_prev < 60:
                bid = max(24.0, highest_prev + 1.0)
            elif highest_prev < 95:
                bid = 34.0
            else:
                bid = 28.0
        else:
            bid = 58.0
            if highest_prev > 0:
                bid = max(58.0, min(78.0, highest_prev * 0.72))

    if urgent_opponents >= 2 and not my_urgent:
        bid *= 0.9
    if rich_opponents >= 2 and slots == 1 and my_urgent:
        bid *= 1.1

    if day >= 8:
        if hp >= 6 and not my_urgent:
            bid *= 0.9
        else:
            bid *= 1.05

    min_safe = 0.0
    if very_urgent:
        min_safe = 85.0
    elif my_urgent:
        min_safe = 65.0

    bid = max(min_safe, bid)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opps = {k:v for k,v in opponents_status.items() if v['alive']}
    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    if prev_bids:
        avg_prev_bid = sum(prev_bids) / len(prev_bids)
    else:
        avg_prev_bid = DAILY_SALARY * 0.5
    if hp <= 2:
        bid = min(budget, max(DAILY_SALARY * 0.9, avg_prev_bid + 5))
    elif hp <= 4:
        bid = min(budget, max(DAILY_SALARY * 0.7, avg_prev_bid + 2))
    else:
        bid = min(budget, max(DAILY_SALARY * 0.4, avg_prev_bid - 5))
    if supply < (WATER_REQ * len(alive_opps) + 1):
        bid = min(budget, max(bid, DAILY_SALARY * 0.8))
    bid = max(1, bid)
    bid = min(budget, bid)
    return bid
